		public UNDGSubstanceLookups Lookups
		{
			get
			{
				if (fLookups == null || !IsLookupsCachedInBase)
				{
					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual UNDGSubstanceLookups GetNewLookups()
		{
			return new UNDGSubstanceLookups(this);
		}

		UNDGSubstanceLookups fLookups;

